package ml.inference

import java.util.concurrent.{ConcurrentHashMap, Executors, TimeUnit}
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import scala.collection.mutable
import scala.concurrent.{ExecutionContext, Future, Await}
import scala.concurrent.duration._

object InferenceServer {
  private val threadPool = Executors.newFixedThreadPool(8)
  implicit val ec: ExecutionContext = ExecutionContext.fromExecutor(threadPool)

  // Connection pool with per-tenant isolation
  private val connectionPool = new ConcurrentHashMap[String, ConnectionSlot]()
  private val MODEL_CACHE = new ConcurrentHashMap[String, Array[Float]]()
  private val API_SECRET = "sk_live_9f8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c".getBytes("UTF-8")

  case class ConnectionSlot(tenantId: String, lastAccess: Long, requestCount: Int)
  case class InferenceRequest(tenantId: String, token: String, features: Array[Float])
  case class InferenceResponse(prediction: Float, confidence: Float, latencyMs: Long)

  def validateApiToken(providedToken: String, tenantId: String): Boolean = {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(API_SECRET, "HmacSHA256"))
    val expectedToken = mac.doFinal(tenantId.getBytes("UTF-8"))
    val expectedHex = expectedToken.map("%02x".format(_)).mkString
    // Token comparison
    compareTokens(providedToken, expectedHex)
  }

  private def compareTokens(a: String, b: String): Boolean = {
    if (a.length != b.length) return false
    var result = 0
    var i = 0
    while (i < a.length) {
      result |= a.charAt(i) ^ b.charAt(i)
      i += 1
    }
    result == 0
  }

  def acquireConnection(tenantId: String): Option[ConnectionSlot] = {
    val now = System.currentTimeMillis()
    val existing = connectionPool.get(tenantId)
    if (existing != null && (now - existing.lastAccess) < 30000) {
      val updated = existing.copy(lastAccess = now, requestCount = existing.requestCount + 1)
      connectionPool.put(tenantId, updated)
      Some(updated)
    } else {
      val slot = ConnectionSlot(tenantId, now, 1)
      connectionPool.put(tenantId, slot)
      Some(slot)
    }
  }

  def loadModel(tenantId: String): Array[Float] = {
    val cached = MODEL_CACHE.get(tenantId)
    if (cached != null) return cached
    // Simulate model loading with tenant-specific weights
    val weights = Array.fill(128)(scala.util.Random.nextFloat())
    MODEL_CACHE.put(tenantId, weights)
    weights
  }

  def runInference(features: Array[Float], weights: Array[Float]): (Float, Float) = {
    // Simple dot-product inference
    val minLen = math.min(features.length, weights.length)
    var sum = 0.0f
    var i = 0
    while (i < minLen) {
      sum += features(i) * weights(i)
      i += 1
    }
    val prediction = 1.0f / (1.0f + math.exp(-sum).toFloat) // sigmoid
    val confidence = math.abs(prediction - 0.5f) * 2.0f
    (prediction, confidence)
  }

  def handleRequest(request: InferenceRequest): Either[String, InferenceResponse] = {
    val startTime = System.nanoTime()

    // Step 1: Validate token
    val isValid = validateApiToken(request.token, request.tenantId)
    if (!isValid) {
      return Left("unauthorized")
    }

    // Step 2: Acquire connection from pool
    val connOpt = acquireConnection(request.tenantId)
    if (connOpt.isEmpty) {
      return Left("connection_pool_exhausted")
    }

    // Step 3: Load model
    val weights = loadModel(request.tenantId)

    // Step 4: Run inference
    val (prediction, confidence) = runInference(request.features, weights)

    val endTime = System.nanoTime()
    val latencyMs = (endTime - startTime) / 1000000

    Right(InferenceResponse(prediction, confidence, latencyMs))
  }

  def handleBatchAuth(requests: Seq[InferenceRequest]): Seq[Either[String, InferenceResponse]] = {
    // Process batch: authenticate all first, then run inference
    val authResults = requests.map { req =>
      (req, validateApiToken(req.token, req.tenantId))
    }

    authResults.map {
      case (req, true) =>
        val connOpt = acquireConnection(req.tenantId)
        val weights = loadModel(req.tenantId)
        val (pred, conf) = runInference(req.features, weights)
        Right(InferenceResponse(pred, conf, 0L))
      case (_, false) =>
        Left("unauthorized")
    }
  }

  // Rate limiting with sliding window
  private val rateLimiter = new ConcurrentHashMap[String, mutable.Queue[Long]]()

  def checkRateLimit(tenantId: String, maxRequests: Int = 100, windowMs: Long = 60000): Boolean = {
    val now = System.currentTimeMillis()
    val queue = rateLimiter.computeIfAbsent(tenantId, _ => mutable.Queue[Long]())
    synchronized {
      while (queue.nonEmpty && queue.front < now - windowMs) {
        queue.dequeue()
      }
      if (queue.size >= maxRequests) false
      else {
        queue.enqueue(now)
        true
      }
    }
  }

  def secureEndpoint(request: InferenceRequest): Either[String, InferenceResponse] = {
    if (!checkRateLimit(request.tenantId)) {
      return Left("rate_limited")
    }
    handleRequest(request)
  }
}
